// =============================================================
// ADMIN DASHBOARD CHARTS
// =============================================================
// This file controls the two approval-status pie charts.
// The actual values come from data-* attributes generated by
// the Razor view because static JavaScript files cannot directly
// access Razor expressions such as @Model.Property.
// =============================================================


// =============================================================
// MARKETPLACE PIE CHART
// =============================================================

// Get the Marketplace canvas element from the current dashboard page.
// If the element does not exist, the script stops so it does not
// cause an error on other pages that may also load this JavaScript file.
const marketplaceCanvas = document.getElementById("marketplaceChart");

if (marketplaceCanvas) {

    // dataset reads HTML data-* attributes.
    // For example, data-approved="1" becomes dataset.approved = "1".
    // Number() converts the string into a numeric value that Chart.js expects.
    const marketplaceApproved =
        Number(marketplaceCanvas.dataset.approved);

    const marketplacePending =
        Number(marketplaceCanvas.dataset.pending);

    const marketplaceRejected =
        Number(marketplaceCanvas.dataset.rejected);


    // Chart.js creates the pie chart using the three approval counts.
    // The values are supplied by the Razor View through the data-* attributes.
    new Chart(marketplaceCanvas, {

        // "pie" tells Chart.js to display the data as a part-to-whole pie chart.
        type: "pie",

        data: {

            // These labels identify each section of the pie chart.
            labels: [
                "Approved",
                "Pending",
                "Rejected"
            ],

            datasets: [{

                // These values determine the size of each pie section.
                data: [
                    marketplaceApproved,
                    marketplacePending,
                    marketplaceRejected
                ]
            }]
        },

        options: {

            // Makes the chart automatically resize according to its container.
            responsive: true,

            plugins: {

                // Places the Approved/Pending/Rejected labels below the chart.
                legend: {
                    position: "bottom"
                }
            }
        }
    });
}


// =============================================================
// LOST & FOUND PIE CHART
// =============================================================

// Find the Lost & Found chart canvas.
const lostFoundCanvas = document.getElementById("lostFoundChart");

if (lostFoundCanvas) {

    // Read the approval counts passed from the Razor View.
    // dataset values are strings, so Number() converts them into numbers.
    const lostFoundApproved =
        Number(lostFoundCanvas.dataset.approved);

    const lostFoundPending =
        Number(lostFoundCanvas.dataset.pending);

    const lostFoundRejected =
        Number(lostFoundCanvas.dataset.rejected);


    // Create the Lost & Found approval-status pie chart.
    new Chart(lostFoundCanvas, {

        // Chart.js uses the pie type to show the proportion
        // of Approved, Pending, and Rejected reports.
        type: "pie",

        data: {

            // Names displayed in the chart legend.
            labels: [
                "Approved",
                "Pending",
                "Rejected"
            ],

            datasets: [{

                // Values determine the size of each pie section.
                data: [
                    lostFoundApproved,
                    lostFoundPending,
                    lostFoundRejected
                ]
            }]
        },

        options: {

            // Allows the chart to resize with its container.
            responsive: true,

            plugins: {

                // Display the chart legend below the pie graph.
                legend: {
                    position: "bottom"
                }
            }
        }
    });
}